package com.cartalaap.notification;
import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PathVariable;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.ResponseStatus;import org.springframework.web.bind.annotation.RestController;
@RestController@RequestMapping("/api/notifications")public class NotificationController{private final NotificationService service;public NotificationController(NotificationService service){this.service=service;}@GetMapping public List<NotificationResponse>list(Authentication auth){return service.list(auth);}@GetMapping("/unread-count")public NotificationResponse.Count count(Authentication auth){return service.count(auth);}@PostMapping("/{id}/read")@ResponseStatus(HttpStatus.NO_CONTENT)public void read(@PathVariable Long id,Authentication auth){service.read(id,auth);}@PostMapping("/read-all")@ResponseStatus(HttpStatus.NO_CONTENT)public void readAll(Authentication auth){service.readAll(auth);}}
